<script setup>
import {ref,onMounted,computed,onUnmounted} from 'vue';
import {api} from './api';import AnalyticsChart from './AnalyticsChart.vue';import SearchableSelect from './SearchableSelect.vue';
const emit=defineEmits(['review-question','solutions']);
const period=ref('7d'),start=ref(''),end=ref(''),course=ref(''),mode=ref(''),data=ref(null),busy=ref(false),error=ref('');let stopped=false;
const params=()=>new URLSearchParams({period:period.value,...(course.value?{course:course.value}:{}),...(mode.value?{mode:mode.value}:{}),...(period.value==='custom'?{start:start.value,end:end.value}:{})}).toString();
async function load(){if(busy.value)return;busy.value=true;error.value='';try{const d=await api('/admin/analytics?'+params());if(!stopped)data.value=d}catch(e){if(!stopped)error.value=e.message}finally{if(!stopped)busy.value=false}}
const number=v=>v==null?'—':Number(v).toLocaleString('en-IN');const percent=v=>v==null?'—':v+'%';
const duration=v=>v==null?'—':v<60?Math.round(v)+' sec':(v/60).toFixed(1)+' min';
const t=computed(()=>data.value?.totals||{}),attention=computed(()=>data.value?.attention||{});
const cards=computed(()=>[
 {name:'Active browsers',value:number(t.value.active_browsers),hint:'Estimated browsers · not verified students',change:change('active_browsers')},
 {name:'Returning browsers',value:number(t.value.returning_browsers),hint:'Activity on multiple recorded IST days'},
 {name:'Attempts started',value:number(t.value.starts),hint:`${number(t.value.exam_starts)} exam · ${number(t.value.practice_starts)} practice`,change:change('starts')},
 {name:'Tests submitted',value:number(t.value.completions),hint:'One recorded submission per attempt',change:change('completions')},
 {name:'Completion rate',value:percent(t.value.completion_rate),hint:`${number(t.value.active)} attempts still active`},
 {name:'Published solutions',value:percent(attention.value.coverage?.percent),hint:`${number(attention.value.coverage?.published)} / ${number(attention.value.coverage?.questions)} visible questions · current course scope`}
]);
function change(key){const v=data.value?.comparison?.change?.[key];return v==null?'':`${v>0?'+':''}${v}% vs previous period`}
const courseOptions=computed(()=>[{value:'',label:'All courses'},...(data.value?.course_options||[]).map(c=>({value:c.key,label:c.name}))]);
const days=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];const hours=Array.from({length:24},(_,i)=>i);
const heat=computed(()=>new Map((data.value?.heatmap||[]).map(r=>[r.weekday+':'+r.hour,r.starts])));
const heatPeak=computed(()=>Math.max(1,...heat.value.values()));
const heatValue=(day,hour)=>heat.value.get(day+':'+hour)||0;
const colors=['#6366f1','#10b981','#38bdf8'];
const devices=computed(()=>data.value?.devices||[]);
const donut=computed(()=>{let offset=0;const sum=devices.value.reduce((n,r)=>n+r.starts,0);if(!sum)return 'var(--line,#e2e8f0)';return 'conic-gradient('+devices.value.map((r,i)=>{const from=offset;offset+=r.starts*100/sum;return `${colors[i%3]} ${from}% ${offset}%`}).join(',')+')'});
const peakCourse=computed(()=>Math.max(1,...(data.value?.courses||[]).map(r=>r.starts)));
const peakScore=computed(()=>Math.max(1,...(data.value?.score_distribution||[]).map(r=>r.count)));
const updated=computed(()=>data.value?.generated_at?new Date(data.value.generated_at*1000).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}):'—');
onMounted(load);onUnmounted(()=>{stopped=true});
</script>
<template><section class="analytics-dashboard">
 <header class="analytics-header"><div><div class="analytics-eyebrow">MAURYAHUB / ADMIN INSIGHTS</div><h2>Practice. Progress. Perspective.</h2><p class="muted">Understand how the platform is used—and what needs your attention.</p></div><span class="analytics-private">Admin only · IST</span></header>
 <form class="panel analytics-controls" @submit.prevent="load"><fieldset class="analytics-fieldset" :disabled="busy"><label>Period<select v-model="period" class="form-select" aria-label="Analytics period" :disabled="busy" @change="period!=='custom'&&load()"><option value="today">Today</option><option value="7d">Last 7 days</option><option value="30d">Last 30 days</option><option value="all">All time</option><option value="custom">Custom range</option></select></label><label>Course<SearchableSelect v-model="course" :options="courseOptions" aria-label="Analytics course" :disabled="busy" placeholder="All courses" @change="load"/></label><label>Mode<select v-model="mode" class="form-select" aria-label="Analytics mode" :disabled="busy" @change="load"><option value="">Exam &amp; practice</option><option value="exam">Exam</option><option value="practice">Practice</option></select></label><template v-if="period==='custom'"><label>From<input type="date" v-model="start" required class="form-control" :disabled="busy"></label><label>To<input type="date" v-model="end" required class="form-control" :disabled="busy"></label></template><div class="analytics-control-actions"><button class="btn btn-primary" :disabled="busy">{{busy?'Loading…':'Refresh'}}</button><a v-if="data&&!busy" :href="'/api/admin/analytics?'+params()+'&format=csv'" class="btn btn-outline-primary">CSV ↓</a></div></fieldset></form>
 <p v-if="error" class="alert alert-danger" role="alert">{{error}}</p><p v-if="!data&&!error" role="status">Loading analytics…</p>
 <template v-if="data"><div class="analytics-meta"><span>{{data.first_day?'Recorded since '+data.first_day:'No recorded attempts yet.'}} · Admin attempts are included from this update onward.</span><span>Updated {{updated}} IST · reports cached 30s</span></div>
 <div class="analytics-kpis"><article v-for="c in cards" :key="c.name" class="panel analytics-kpi"><span>{{c.name}}</span><strong>{{c.value}}</strong><small>{{c.hint}}</small><span v-if="c.change" class="analytics-change">{{c.change}}</span></article></div>
 <div class="analytics-grid"><section class="panel analytics-wide"><div class="analytics-section-heading"><div><h3>Daily activity</h3><p>Starts and submissions by the attempt's IST start date · up to 90 days.</p></div><span class="analytics-tag">Growth</span></div><AnalyticsChart :rows="data.trend" :series="[{key:'starts',name:'Starts'},{key:'completions',name:'Submissions'}]" label="Daily starts and submissions"/><p v-if="!t.starts" class="muted">No activity in this range.</p></section>
 <section class="panel"><div class="analytics-section-heading"><div><h3>Exam or practice?</h3><p>How each day's attempts begin.</p></div></div><AnalyticsChart :rows="data.trend" kind="stacked" :series="[{key:'exam_starts',name:'Exam'},{key:'practice_starts',name:'Practice'}]" label="Daily exam versus practice starts"/></section>
 <section class="panel"><div class="analytics-section-heading"><div><h3>Weekly engagement</h3><p>Distinct active browsers each week; edge weeks may be partial.</p></div></div><AnalyticsChart :rows="data.weekly||[]" label-key="week_start" :series="[{key:'active_browsers',name:'Active browsers'},{key:'completions',name:'Submissions'}]" label="Weekly active browsers and submissions"/></section>
 <section class="panel"><div class="analytics-section-heading"><div><h3>Course demand</h3><p>Top courses by starts in the selected range.</p></div></div><div v-for="r in (data.courses||[]).slice(0,10)" :key="r.key" class="analytics-rank"><div><span>{{r.name}}</span><strong>{{number(r.starts)}}</strong></div><div class="analytics-track"><span :style="{width:100*r.starts/peakCourse+'%'}"/></div></div><p v-if="!data.courses?.length" class="muted">No course activity yet.</p></section>
 <section class="panel"><div class="analytics-section-heading"><div><h3>Device mix</h3><p>Coarse device type; no fingerprinting.</p></div></div><div class="analytics-device"><div class="analytics-donut" :style="{background:donut}" role="img" :aria-label="'Device mix: '+devices.map(r=>r.name+' '+r.starts).join(', ')"><div><strong>{{number(t.starts)}}</strong><small>starts</small></div></div><div><p v-for="(r,i) in devices" :key="r.name"><i class="analytics-key" :style="{background:colors[i%3]}"/>{{r.name}} <strong>{{r.starts}}</strong></p><p v-if="!devices.length" class="muted">No device data yet.</p></div></div></section>
 <section class="panel"><div class="analytics-section-heading"><div><h3>Attempt outcomes</h3><p>Active attempts are separate from expired sessions.</p></div></div><div class="analytics-outcomes"><div><strong>{{number(t.completions)}}</strong><span>Submitted</span></div><div><strong>{{number(t.active)}}</strong><span>Still active</span></div><div><strong>{{number(t.abandoned)}}</strong><span>Expired, not submitted</span></div></div><p class="muted small">Completion rate {{percent(t.completion_rate)}} · Drop-off {{percent(t.dropoff_rate)}}. An expired session does not identify why someone left.</p><p class="muted small">Average completion duration: {{duration(t.average_seconds)}} · includes idle time. Timer-triggered submissions: {{number(t.automatic)}}.</p></section>
 <section class="panel analytics-wide"><div class="analytics-section-heading"><div><h3>When practice happens</h3><p>Attempt starts · IST · hover a cell for the exact count.</p></div><span class="analytics-tag">Weekly rhythm</span></div><div class="analytics-heat-scroll"><div class="analytics-heatmap" role="img" aria-label="Attempt starts by IST weekday and hour"><span></span><span v-for="h in hours" :key="'h'+h">{{h.toString().padStart(2,'0')}}</span><template v-for="(d,i) in days" :key="d"><strong>{{d}}</strong><span v-for="h in hours" :key="d+h" class="heat-cell" :style="{background:`rgba(99,102,241,${heatValue(i,h)?(.18+.82*heatValue(i,h)/heatPeak):.05})`}" :title="`${d} ${h}:00–${h}:59 IST · ${heatValue(i,h)} starts`"><span class="visually-hidden">{{d}} {{h}}:00: {{heatValue(i,h)}}</span></span></template></div></div><details class="small mt-3"><summary>View heatmap counts</summary><div class="table-responsive"><table class="table"><thead><tr><th>IST</th><th v-for="h in hours" :key="h">{{h}}:00</th></tr></thead><tbody><tr v-for="(d,i) in days" :key="d"><th>{{d}}</th><td v-for="h in hours" :key="h">{{heatValue(i,h)}}</td></tr></tbody></table></div></details><p class="muted small mt-3">Darker = more starts. This is a time-of-day summary, not a live concurrent-user count.</p></section>
 <section class="panel"><div class="analytics-section-heading"><div><h3>Score distribution</h3><p>Reliably graded, unassisted exam submissions only.</p></div></div><div v-for="r in data.score_distribution||[]" :key="r.name" class="analytics-rank"><div><span>{{r.name}}</span><strong>{{number(r.count)}}</strong></div><div class="analytics-track"><span :style="{width:100*r.count/peakScore+'%'}"/></div></div><p class="muted small">Average {{percent(t.average_score)}} · {{number(t.scored_exams)}} recorded exam scores. Older scores that were not recorded remain unavailable.</p></section></div>
 <section class="panel analytics-attention"><div class="analytics-section-heading"><div><div class="analytics-eyebrow">WHAT TO DO NEXT</div><h3>Needs attention</h3><p>Use demand and content signals to choose the next improvement.</p></div><span class="analytics-tag">{{number(attention.open_reports)}} open reports</span></div><div class="analytics-attention-grid"><article><h4>Popular papers needing solutions</h4><p class="muted small">Current published coverage; popularity uses the selected date and mode.</p><div v-for="p in attention.unsolved||[]" :key="p.id" class="analytics-task"><strong>{{p.course}} · {{p.name}}</strong><span>{{p.starts}} starts · {{p.published}}/{{p.total}} published · {{p.missing}} missing</span><button class="text-btn" @click="emit('solutions',p.id)">Upload / review solutions →</button></div><p v-if="!attention.unsolved?.length" class="muted">No unsolved papers among the most popular results.</p></article><article><h4>Formatting reports</h4><div v-for="r in attention.reports||[]" :key="r.id" class="analytics-task"><strong>Paper #{{r.paper_id}} · Q{{r.number}}</strong><span>{{r.issue}}</span><button class="text-btn" @click="emit('review-question',r.question_id)">Review question →</button></div><p v-if="!attention.reports?.length" class="muted">No open reports in this course scope.</p></article><article><h4>Questions worth checking</h4><p class="muted small">Below 30% fully correct, with at least 20 graded unassisted exam responses for the same question version. A signal to investigate—not proof of a bad key.</p><div v-for="q in attention.questions||[]" :key="q.question_id" class="analytics-task"><strong>{{q.paper}} · Q{{q.number}}</strong><span>{{q.accuracy}}% fully correct · {{q.graded}} graded responses · {{q.partial}} partial</span><button class="text-btn" @click="emit('review-question',q.question_id)">Inspect question →</button></div><p v-if="!attention.questions?.length" class="muted">No qualifying question signals yet.</p></article><article><h4>Lower-scoring papers</h4><p class="muted small">Below 50% average, with at least 20 scored exams. Check difficulty and content before drawing conclusions.</p><div v-for="p in attention.low_score_papers||[]" :key="p.key" class="analytics-task"><strong>{{p.name}}</strong><span>{{p.average_score}}% average · {{p.scored_exams}} scored exams</span></div><p v-if="!attention.low_score_papers?.length" class="muted">Not enough evidence to flag a paper.</p></article></div><p class="muted small mt-3">Current solution coverage and open reports are cached for up to 2 minutes and are independent of the date/mode filters. Question accuracy uses the selected dates; practice-only views omit that signal.</p></section>
 <section class="panel"><div class="analytics-section-heading"><div><h3>Paper performance</h3><p>Top 50 papers by starts. Overall cards include every matching record.</p></div></div><div class="table-responsive"><table class="table analytics-table"><thead><tr><th>Paper</th><th>Starts</th><th>Submitted</th><th>Completion</th><th>Browsers</th><th>Avg duration</th><th>Exam score</th></tr></thead><tbody><tr v-for="p in data.papers||[]" :key="p.key"><td>{{p.name}}</td><td>{{p.starts}}</td><td>{{p.completions}}</td><td>{{percent(p.completion_rate)}}</td><td>{{p.active_browsers}}</td><td>{{duration(p.average_seconds)}}</td><td>{{percent(p.average_score)}} <small>({{p.scored_exams||0}})</small></td></tr><tr v-if="!data.papers?.length"><td colspan="7">No activity in this range.</td></tr></tbody></table></div></section>
 <details class="panel analytics-definitions"><summary>How to read these numbers</summary><p>One new successful paper attempt counts as one start. A mode switch adds no start; a repeated submit adds no second completion. Exam-started attempts that used practice are excluded from unassisted exam scores. Admin attempts count like any other student's attempts from this update onward; unrecorded past admin activity is not invented.</p><p>Active/new/returning browser estimates use a first-party pseudonymous cookie, not names, IPs or fingerprinting. A returning browser has activity on multiple recorded IST days (or before this range); a new browser has only its first recorded day. Clearing cookies/changing devices affects counts. These are practice users, not total website visitors.</p><p>Scores start recording with this update. Daily question outcome totals are stored separately from browser identifiers, without selected options or typed answers. Outdated question versions are excluded from the question-review signal. Successful records survive temporary attempt cleanup. Historical scores and missing analytics are never fabricated.</p><p>Reports are generated only when this tab opens or you change filters/refresh. No polling or per-question analytics request is added. Writes share the existing start/submit transaction with an isolated savepoint; failures are logged without intentionally failing the exam action, so incomplete counts are possible. Duration includes idle time and drop-off reasons are unknown. Shared database resources are finite.</p></details>
 </template></section></template>
<style scoped>
.analytics-dashboard{--analytics-accent:#6366f1}.analytics-header{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;margin:12px 0 24px}.analytics-eyebrow{font-size:10px;letter-spacing:1.7px;font-weight:700;color:var(--muted,#64748b);margin-bottom:8px}.analytics-header h2{font-size:clamp(25px,3vw,36px);letter-spacing:-1px;margin:0 0 10px}.analytics-header p{margin:0}.analytics-private,.analytics-tag{white-space:nowrap;font-size:11px;border:1px solid var(--line);border-radius:30px;padding:7px 11px;color:var(--muted,#64748b)}.analytics-fieldset{display:contents;border:0;padding:0;margin:0}.analytics-controls{display:flex;align-items:flex-end;flex-wrap:wrap;gap:12px;padding:18px}.analytics-controls label{flex:1;min-width:150px;font-size:12px;font-weight:600}.analytics-controls :deep(.searchable-select){margin-top:0}.analytics-controls select,.analytics-controls input{margin-top:6px}.analytics-control-actions{display:flex;gap:8px}.analytics-meta{display:flex;justify-content:space-between;gap:14px;flex-wrap:wrap;font-size:11px;color:var(--muted,#64748b);margin:15px 0}.analytics-kpis{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-bottom:20px}.analytics-kpi{padding:20px;margin:0;display:flex;flex-direction:column;gap:8px;border-top:3px solid #6366f155}.analytics-kpi>span:first-child{font-size:12px;font-weight:600;color:var(--muted,#64748b)}.analytics-kpi strong{font-size:32px;letter-spacing:-1.3px;line-height:1.2}.analytics-kpi small{font-size:11px;color:var(--muted,#64748b)}.analytics-change{font-size:11px;color:var(--analytics-accent)}.analytics-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;margin-bottom:18px}.analytics-grid>.panel{min-width:0;margin:0;padding:22px}.analytics-wide{grid-column:1/-1}.analytics-section-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;margin-bottom:20px}.analytics-section-heading h3{font-size:17px;margin:0 0 7px;letter-spacing:-.3px}.analytics-section-heading p{font-size:12px;color:var(--muted,#64748b);margin:0;line-height:1.6}.analytics-rank{margin:17px 0}.analytics-rank>div:first-child{display:flex;justify-content:space-between;gap:10px;font-size:12px;margin-bottom:7px}.analytics-track{height:7px;border-radius:6px;background:#64748b14;overflow:hidden}.analytics-track>span{height:100%;display:block;background:#6366f1;border-radius:6px}.analytics-device{display:flex;align-items:center;justify-content:center;gap:28px;min-height:200px}.analytics-donut{width:155px;height:155px;border-radius:50%;display:grid;place-items:center;flex-shrink:0}.analytics-donut>div{width:113px;height:113px;border-radius:50%;background:var(--panel,#fff);display:flex;align-items:center;justify-content:center;flex-direction:column}.analytics-donut strong{font-size:26px}.analytics-donut small{font-size:11px;color:var(--muted,#64748b)}.analytics-device p{display:flex;align-items:center;gap:8px;font-size:12px}.analytics-key{display:inline-block;width:9px;height:9px;border-radius:3px}.analytics-outcomes{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:30px 0}.analytics-outcomes div{border-left:3px solid #6366f1;padding-left:12px}.analytics-outcomes div:first-child{border-color:#10b981}.analytics-outcomes div:last-child{border-color:#94a3b8}.analytics-outcomes strong{display:block;font-size:28px}.analytics-outcomes span{font-size:11px;color:var(--muted,#64748b)}.analytics-heat-scroll{overflow-x:auto}.analytics-heatmap{display:grid;grid-template-columns:40px repeat(24,minmax(16px,1fr));gap:5px;min-width:650px;align-items:center}.analytics-heatmap>span:not(.heat-cell),.analytics-heatmap>strong{font-size:10px;color:var(--muted,#64748b)}.heat-cell{height:24px;border-radius:4px;outline:1px solid #64748b10}.analytics-attention{margin:18px 0;padding:24px;border-top:3px solid #10b981}.analytics-attention-grid{display:grid;grid-template-columns:1fr 1fr;gap:26px}.analytics-attention h4{font-size:14px}.analytics-task{display:flex;flex-direction:column;align-items:flex-start;gap:5px;padding:13px 0;border-bottom:1px solid var(--line)}.analytics-task strong{font-size:12px}.analytics-task span,.analytics-task button{font-size:11px}.analytics-task span{color:var(--muted,#64748b)}.analytics-table{font-size:12px}.analytics-table th{white-space:nowrap;font-weight:600}.analytics-table td:first-child{min-width:180px}.analytics-definitions{font-size:12px;line-height:1.8;margin-top:20px}.analytics-definitions p{margin:14px 0 0}
@media(min-width:1500px){.analytics-kpis{grid-template-columns:repeat(6,minmax(0,1fr))}.analytics-kpi strong{font-size:28px}}@media(max-width:700px){.analytics-header{flex-direction:column;gap:12px}.analytics-kpis{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.analytics-kpi{padding:15px}.analytics-kpi strong{font-size:26px}.analytics-grid{grid-template-columns:1fr}.analytics-wide{grid-column:auto}.analytics-grid>.panel{padding:17px}.analytics-attention-grid{grid-template-columns:1fr}.analytics-controls label{min-width:130px}.analytics-controls{padding:15px}.analytics-device{gap:18px}.analytics-private{align-self:flex-start}.analytics-section-heading .analytics-tag{display:none}}
[data-theme="dark"] .analytics-dashboard{--analytics-accent:#a5b4fc}[data-theme="dark"] .analytics-donut>div{background:var(--panel,#172033)}
</style>
